// Golden parity: the Dart VMC port == the REAL web utils/vmcSheet.js and
// utils/vmcValidation.js (fixtures generated by tool/gen_vmc_golden.mjs).
import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:indo/features/production/processes/vmc/vmc_calc.dart';
import 'package:indo/features/production/processes/vmc/vmc_spec.dart';
import 'package:indo/features/production/processes/vmc/vmc_validation.dart';
import 'package:indo/features/production/shared/production_sheet_calc.dart' show sortByMachineOn;

import '../../calc/golden_support.dart';

// VMC_FIXTURE_DIR points a one-off soak run at freshly generated fixtures (SEED=.. SCALE=..).
final dir = Platform.environment['VMC_FIXTURE_DIR'] ?? 'test/production/processes/vmc/fixtures';

Map<String, dynamic> _m(Object? v) => Map<String, dynamic>.from(v as Map);

void main() {
  group('golden: vmcRowCalc / programCycleSec', () {
    final cases = loadFixture('row_calc.json', dir: dir) as List;
    test('${cases.length} rows match the web', () {
      expect(cases.length, greaterThan(500));
      for (var i = 0; i < cases.length; i++) {
        final c = cases[i] as Map;
        final d = diff(vmcSpec.rowCalc(_m(c['row'])), c['out']);
        expect(d, isNull, reason: 'case $i ${showCase(c['row'])}: $d');
      }
    });

    test('Product Cycle Time from the program', () {
      final cycle = loadFixture('cycle.json', dir: dir) as List;
      for (var i = 0; i < cycle.length; i++) {
        final c = cycle[i] as Map;
        expect(diff(programCycleSec(_m(c['row'])), c['out']), isNull, reason: 'cycle case $i ${showCase(c['row'])}');
      }
    });

    test('Ideal Quantity is floored from the numbers typed (7 min / 9 pcs)', () {
      final calc = vmcRowCalc({'itemName': 'P', 'programTimeMin': '7', 'pcsPerProgram': '9', 'machineOnTime': '08:00', 'machineOffTime': '16:00'});
      expect(calc['totalCycleSec'], closeTo(7 * 60 / 9, 1e-9));
      expect(calc['idealQty'], (480 * 9 / 7).floor());
    });

    test('null row -> empty map', () => expect(vmcRowCalc(null), isEmpty));
  });

  group('golden: vmcDayCalc', () {
    final cases = loadFixture('day_calc.json', dir: dir) as List;
    test('${cases.length} machine-days match the web', () {
      for (var i = 0; i < cases.length; i++) {
        final c = cases[i] as Map;
        final rows = [for (final r in c['rows'] as List) _m(r)];
        // The page feeds the day calc rows sorted by Machine ON time.
        final sorted = sortByMachineOn(rows);
        expect(diff([for (final r in sorted) _m(r)], [for (final r in c['sorted'] as List) r]), isNull, reason: 'sort case $i');
        final d = diff(vmcSpec.dayCalc(sorted), c['out']);
        expect(d, isNull, reason: 'day case $i ${showCase(c['rows'])}: $d');
      }
    });
  });

  group('golden: validateVmcEntry / field order / firstError', () {
    final cases = loadFixture('validation.json', dir: dir) as List;
    test('${cases.length} blocks give the web\'s messages, in the web\'s key order', () {
      var withErrors = 0, clean = 0;
      for (var i = 0; i < cases.length; i++) {
        final c = cases[i] as Map;
        final saved = c['saved'] == null ? null : _m(c['saved']);
        final actual = vmcSpec.validateEntry(_m(c['values']), saved: saved);
        final d = diff(actual, c['errors']);
        expect(d, isNull, reason: 'case $i ${showCase(c['values'])} saved=${showCase(saved)}: $d');
        // Same order of keys as the web's object.
        expect(actual.keys.toList(), (c['errors'] as Map).keys.toList(), reason: 'key order case $i');
        (actual.isEmpty ? clean++ : withErrors++);
      }
      expect(withErrors, greaterThan(100));
      expect(clean, greaterThan(10), reason: 'the fixture must also exercise the all-valid path');
    });

    test('field order and downtime keys', () {
      final f = loadFixture('first_error.json', dir: dir) as Map;
      expect(vmcSpec.fieldOrder, f['fieldOrder']);
      expect(vmcDowntimeKeys, f['downtimeKeys']);
      for (final c in f['cases'] as List) {
        final errors = [
          for (final e in (c as Map)['errors'] as List) e == null ? null : Map<String, String>.from(e as Map),
        ];
        final got = vmcSpec.firstError(errors);
        final want = c['out'];
        expect(diff(got, want), isNull, reason: 'firstError ${showCase(errors)}');
      }
    });
  });

  group('golden: toPayload', () {
    final cases = loadFixture('payload.json', dir: dir) as List;
    test('${cases.length} payloads equal the web handler\'s body', () {
      for (var i = 0; i < cases.length; i++) {
        final c = cases[i] as Map;
        final actual = vmcSpec.toPayload(_m(c['values']), isEdit: c['isEdit'] as bool);
        final d = diff(actual, c['payload']);
        expect(d, isNull, reason: 'payload case $i ${showCase(c['values'])} edit=${c['isEdit']}: $d');
      }
    });
  });

  group('formulas', () {
    test('the web VMC_FORMULAS texts are carried over verbatim', () {
      final web = loadFixture('formulas.json', dir: dir) as Map;
      for (final e in web.entries) {
        expect(vmcSpec.formulas[e.key], e.value, reason: 'formula ${e.key}');
      }
      expect(vmcSpec.formulas.containsKey('rejectedQty'), isFalse);
    });
  });

  group('values by hand', () {
    final now = DateTime(2026, 10, 22);
    test('a saved row loads as form values (planned shift as H.MM, numbers as text)', () {
      final v = vmcSpec.toFormValues({
        '_id': 'r1',
        'date': '2026-10-20',
        'machine': 'm1',
        'slot': 2,
        'item': 'i1',
        'itemName': 'Bracket',
        'programTimeMin': 7,
        'pcsPerProgram': 9,
        'okQty': 40,
        'rejectedQty': 0,
        'plannedOperatorShiftHours': 8.5,
        'lunchMin': 30,
        'workingMode': null,
        'machineStatus': ['No Planning'],
      }, now: now);
      expect(v['plannedOperatorShiftHours'], '8.30');
      expect(v['okQty'], '40');
      expect(v['rejectedQty'], '0');
      expect(v['programTimeMin'], '7');
      expect(v['workingMode'], 'Working');
      expect(v['slot'], 2);
      expect(v['setupMin'], '');
    });

    test('picking a Part copies its program; a different part lets go of the work order', () {
      final v = vmcSpec.applyItemSelection(
        {...vmcSpec.emptyEntry(now: now), 'workOrder': 'w1', 'workOrderNo': 'WO-1', 'excludedOps': ['programTimeMin']},
        'i2',
        [
          {'_id': 'i2', 'itemName': 'Flange', 'drawingNo': 'F-7', 'programTimeMin': 12.5, 'pcsPerProgram': 4, 'setupNo': 'S9'},
        ],
      );
      expect([v['item'], v['itemName'], v['drawingNo'], v['setupNo'], v['programTimeMin'], v['pcsPerProgram']], ['i2', 'Flange', 'F-7', 'S9', '12.5', '4']);
      expect(v['excludedOps'], isEmpty);
      expect([v['workOrder'], v['workOrderNo']], ['', '']);
    });

    test('drafts, new blocks and "has data"', () {
      final a = vmcSpec.emptyEntry(now: now);
      expect(vmcSpec.entryHasData(a), isFalse);
      expect(vmcSpec.entryHasData({...a, 'rejectedQty': '0'}), isTrue);
      expect(vmcSpec.entryHasData({...a, 'workingMode': 'Non Working'}), isTrue);
      expect(vmcSpec.entryHasData({...a, 'machineStatus': ['No Manpower']}), isTrue);
      expect(vmcSpec.hasAnyEntryData([a]), isFalse);
      expect(vmcSpec.hasAnyEntryData([{...a, 'machine': 'm1'}]), isTrue);
      expect(vmcSpec.hasAnyEntryData([{...a, 'programTimeMin': '5'}]), isTrue);
      expect(vmcSpec.newBlockAfter([{...a, 'date': '2026-10-01'}], now: now)['date'], '2026-10-01');
      expect(vmcSpec.newBlockAfter(const [], now: now)['date'], '2026-10-22');
      final merged = vmcSpec.mergeDraftEntry({'machine': 'm9', 'okQty': '3'}, now: now);
      expect(merged['machine'], 'm9');
      expect(merged['rejectedQty'], '');
      expect(merged['excludedOps'], isEmpty);
      expect(merged['workingMode'], 'Working');
    });

    test('identity and routing', () {
      expect(vmcSpec.key, 'vmc');
      expect(vmcSpec.routePath, '/production/vmc-data-entry');
      expect(vmcSpec.draftKey, 'vmcEntryDraft');
      expect(vmcSpec.api.row, endsWith('/vmc-sheet/row'));
      expect(vmcSpec.scopeItemsToProcess, isTrue);
    });
  });
}
